using System.Collections.Frozen;

namespace CombatSolver.HotKernel;

internal readonly record struct HotRelicCatalogEntry(
    HotRelicId Id,
    string Entry,
    HotHookMask HookMask,
    bool IsStateful,
    bool IsTracked,
    bool CanHealPlayer,
    bool CanGenerateUnknown);

/// <summary>
/// Static STS2 0.113.1 catalog covering all vanilla concrete relics with exact hook masks and capability flags.
/// </summary>
internal static class HotRelicCatalog
{
    public static readonly HotRelicCatalogEntry[] ById = BuildById();
    public static readonly FrozenDictionary<string, HotRelicId> IdByEntry = BuildIdByEntry();

    public static HotRelicId FindByEntry(string entry)
        => IdByEntry.TryGetValue(entry, out HotRelicId id) ? id : HotRelicId.None;

    public static ref readonly HotRelicCatalogEntry Get(HotRelicId id)
    {
        int idx = (int)id;
        return ref ById[(uint)idx < (uint)ById.Length ? idx : 0];
    }

    public static HotHookMask GetHookMask(string entry)
        => Get(FindByEntry(entry)).HookMask;

    private static FrozenDictionary<string, HotRelicId> BuildIdByEntry()
    {
        Dictionary<string, HotRelicId> map = new(ById.Length, StringComparer.Ordinal);
        for (int i = 1; i < ById.Length; i++)
            map[ById[i].Entry] = ById[i].Id;
        return map.ToFrozenDictionary(StringComparer.Ordinal);
    }

